import (
	"crypto/rand"
	"crypto/sha256"
	"encoding/hex"
	"golang.org/x/crypto/pbkdf2"
)

func hashPasswords(count int, usernames []string, passwords []string) [][2]string {
	if count <= 0 {
		return [][2]string{}
	}
	if len(usernames) < count || len(passwords) < count {
		return [None]
	}
	result := [][2]string{}
	for i := 0; i < count; i++ {
		salt := make([]byte, 32)
		if _, err := rand.Read(salt); err != nil {
			continue
		}
		hash := pbkdf2.Key([]byte(passwords[i]), salt, 10000, 32, sha256.New())
		hashedPassword := hex.EncodeToString(hash)
		result = append(result, [2]string{hashedPassword, hex.EncodeToString(salt)})
	}
	return result
}
